const input = $json.body ?? $json;
const text = (v) => v === null || v === undefined ? '' : String(v).trim();
const bool = (v) => typeof v === 'boolean' ? v : ['true','1','yes','on'].includes(text(v).toLowerCase());
const norm = (v) => text(v).replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/\u200c/g,' ').replace(/\s+/g,' ').trim();

const clinic_name = text(input.clinic_name);
const question = norm(input.question);
const normalized_query = norm(input.normalized_query || question);
const specialty = text(input.specialty || 'general').toLowerCase();
const service_name = text(input.service_name);
const top_k = Number(input.top_k ?? 8);
const min_score = Number(input.min_score ?? 0.18);
const session_id = Number(input.session_id ?? 0);
const message_id = Number(input.message_id ?? 0);
const clinical_intake_case_id = Number(input.clinical_intake_case_id ?? 0);
const confirm_query = bool(input.confirm_query);

let keywords = input.keywords ?? [];
try { if (typeof keywords === 'string') keywords = JSON.parse(keywords || '[]'); } catch { keywords = null; }

const errors = [];
if (!clinic_name) errors.push({field:'clinic_name',message:'نام کلینیک الزامی است.'});
if (!question) errors.push({field:'question',message:'سؤال الزامی است.'});
if (question.length > 8000) errors.push({field:'question',message:'سؤال بیش از حد طولانی است.'});
if (!Array.isArray(keywords)) {
  errors.push({field:'keywords',message:'keywords باید آرایه باشد.'});
  keywords = [];
}
keywords = keywords.map(norm).filter(Boolean).slice(0,30);
if (!Number.isInteger(top_k) || top_k < 1 || top_k > 30) errors.push({field:'top_k',message:'top_k معتبر نیست.'});
if (!Number.isFinite(min_score) || min_score < 0 || min_score > 1) errors.push({field:'min_score',message:'min_score معتبر نیست.'});
for (const [field,value] of Object.entries({session_id,message_id,clinical_intake_case_id})) {
  if (!Number.isInteger(value) || value < 0) errors.push({field,message:`${field} معتبر نیست.`});
}
if (confirm_query !== true) errors.push({field:'confirm_query',message:'جست‌وجو باید تأیید شود.'});

return [{json:{
  clinic_name,question,normalized_query,specialty,service_name,
  keywords_json:JSON.stringify(keywords),top_k,min_score,session_id,message_id,
  clinical_intake_case_id,confirm_query,
  validation_status:errors.length?'invalid':'valid',errors
}}];
